  background: var(--bg-deep);
  border: 1px solid var(--border);
  border-radius: 8px;
  padding: 6px 12px;
  font-family: 'SF Mono', Menlo, monospace;
  font-size: 13px;
  color: var(--primary-dark);
  font-weight: 700;
  margin-top: 6px;
  cursor: pointer;
  transition: background 0.2s;
}
.url-code:hover { background: var(--bg-warm); }

.toast {
  position: fixed;
  bottom: 32px;
  left: 50%;
  transform: translateX(-50%) translateY(80px);
  background: var(--green-dark);
  color: #fff;
  padding: 14px 28px;
  border-radius: 999px;
  font-weight: 700;
  font-size: 15px;
  box-shadow: var(--shadow-lg);
  opacity: 0;
  transition: all 0.3s;
  z-index: 999;
  pointer-events: none;
}
.toast.show {
  opacity: 1;
  transform: translateX(-50%) translateY(0);
}
</style>
