17	    border-radius:16px; padding:32px 28px; margin-bottom:24px;
18	  }
19	  h1 { font-size:22px; font-weight:900; text-align:center; margin-bottom:8px; }
20	  h1 span { color:var(--gold); }
21	  p.sub { text-align:center; color:rgba(255,255,255,.6); font-size:14px; margin-bottom:24px; }
22	  .drop {
23	    border:2px dashed var(--line); border-radius:12px; padding:32px 16px; text-align:center;
24	    color:rgba(255,255,255,.7); font-size:15px; margin-bottom:16px;
25	  }
26	  input[type=file] { width:100%; margin-top:14px; color:#fff; }
27	  button {
28	    width:100%; margin-top:20px; padding:14px; font-size:17px; font-weight:900; border:none;
29	    border-radius:8px; background:var(--gold); color:var(--dark); cursor:pointer;
30	  }
31	  .error { margin-top:16px; padding:10px 12px; background:rgba(220,80,80,.15); border:1px solid rgba(220,80,80,.4);
32	    border-radius:8px; color:#ff9b9b; font-size:15px; text-align:center; }
33	  .success { margin-top:16px; padding:12px 14px; background:rgba(76,175,125,.15); border:1px solid rgba(76,175,125,.4);
34	    border-radius:8px; color:#8fe0b8; font-size:15px; text-align:center; }
35	  .hint { margin-top:14px; font-size:13px; color:rgba(255,255,255,.45); line-height:1.6; }
36	  .sites { width:100%; max-width:520px; }
37	  .sites h2 { font-size:16px; color:var(--gold); margin-bottom:12px; }
38	  .site-row {
39	    background:var(--dark2); border:1px solid var(--line); border-radius:10px; padding:14px 16px;
40	    margin-bottom:10px; display:flex; justify-content:space-between; align-items:center; gap:12px;
41	  }
42	  .site-row .name { font-weight:700; font-size:15px; }
43	  .site-row .meta { font-size:12px; color:rgba(255,255,255,.5); margin-top:2px; }
44	  .site-row a { color:var(--gold); text-decoration:none; font-size:13px; white-space:nowrap; }
45	  .status-pending { color:#f0c674; }
46	  .status-live { color:var(--green); }
47	  .status-failed { color:#ff9b9b; }
48	  .empty { color:rgba(255,255,255,.4); font-size:14px; text-align:center; padding:20px 0; }
